from click import command, echo_via_pager
from click.testing import CliRunner
import sys

@command()
def cli():
    echo_via_pager("Hello, Click!")
    print(f"Inside command, sys.stdout.closed: {sys.stdout.closed}", file=sys.__stderr__)
    if hasattr(sys.stdout, 'buffer'):
        print(f"Inside command, sys.stdout.buffer.closed: {sys.stdout.buffer.closed}", file=sys.__stderr__)

try:
    result = CliRunner().invoke(cli)
    print(repr(result.output))
except ValueError as e:
    print(f"Caught expected error: {e}", file=sys.__stderr__)
